'use client'

import { Heart } from 'lucide-react'
import { useFavoris } from '@/contexts/FavorisContext'

export default function BoutonFavori({ lieu, size = 24, className = '' }) {
  const { estFavori, toggleFavori } = useFavoris()
    console.log('Lieu dans BoutonFavori:', lieu)
  const isFavori = estFavori(lieu.id)

  return (
    <button
      onClick={(e) => {
        e.stopPropagation() // Empêche le clic de se propager (utile si dans une carte cliquable)
        toggleFavori(lieu)
      }}
      className={`
        group relative p-2 rounded-full transition-all duration-200
        ${isFavori 
          ? 'bg-red-50 hover:bg-red-100' 
          : 'bg-gray-50 hover:bg-gray-100'
        }
        ${className}
      `}
      title={isFavori ? 'Retirer des favoris' : 'Ajouter aux favoris'}
    >
      <Heart 
        size={size} 
        className={`transition-all duration-200 ${
          isFavori 
            ? 'fill-red-500 text-red-500' 
            : 'text-gray-400 group-hover:text-red-400'
        }`}
      />
      
      {/* Animation lors de l'ajout */}
      {isFavori && (
        <span className="absolute inset-0 rounded-full bg-red-400 opacity-25"></span>
      )}
    </button>
  )
}